INSERT INTO tailor (slug, display_name, description, shop_address_text, home_visits, languages, price_note, price_confirmed_on, whatsapp_e164, phone_e164, status, is_published, published_at, permission_recorded, permission_note, permission_date, contact_publish_consent, verified_fields, fee_terms_text, fee_terms_agreed_on, private_contact_name, private_phone, created_at, updated_at) VALUES ('atelier-lorosae', 'Atelier Lorosae', 'A family tailoring shop in Vera Cruz making suits, formal shirts and wedding outfits since 2009. Fittings in the shop, or at your home with two weeks notice for wedding orders.', 'Rua Presidente Nicolau Lobato, Vera Cruz, Dili', 'yes', 'Tetum, Portuguese, English', 'Prices depend on the cloth. You can bring your own or choose from ours.', date('now','-10 days'), '+67070000011', '+67070000012', 'approved', 1, strftime('%Y-%m-%dT%H:%M:%fZ','now','-40 days','-0 hours'), 1, 'Agreed by phone and WhatsApp message with the owner', date('now','-44 days'), 1, '["description", "languages", "home_visits", "whatsapp"]', '10% of the order value, due after the customer collects the order', date('now','-40 days'), 'Anselmo (owner)', '+67070000013', strftime('%Y-%m-%dT%H:%M:%fZ','now','-60 days','-0 hours'), strftime('%Y-%m-%dT%H:%M:%fZ','now','-59 days','-0 hours'));
INSERT INTO tailor (slug, display_name, description, shop_address_text, home_visits, languages, price_note, price_confirmed_on, whatsapp_e164, phone_e164, status, is_published, published_at, permission_recorded, permission_note, permission_date, contact_publish_consent, verified_fields, fee_terms_text, fee_terms_agreed_on, private_contact_name, private_phone, created_at, updated_at) VALUES ('tais-moderna', 'Tais Moderna', 'Modern dresses, blouses and jackets sewn from tais cloth, and traditional wear for ceremonies and graduations. Bring your own tais or choose from ours.', 'Near the Comoro market, Dom Aleixo, Dili', 'no', 'Tetum, Portuguese', 'Tais cloth is not included unless agreed.', date('now','-10 days'), '+67070000021', NULL, 'approved', 1, strftime('%Y-%m-%dT%H:%M:%fZ','now','-30 days','-0 hours'), 1, 'Agreed in person at the shop', date('now','-35 days'), 1, '["description", "whatsapp"]', '10% of the order value', date('now','-33 days'), 'Madalena', '+67070000022', strftime('%Y-%m-%dT%H:%M:%fZ','now','-50 days','-0 hours'), strftime('%Y-%m-%dT%H:%M:%fZ','now','-49 days','-0 hours'));
INSERT INTO tailor (slug, display_name, description, shop_address_text, home_visits, languages, price_note, price_confirmed_on, whatsapp_e164, phone_e164, status, is_published, published_at, permission_recorded, permission_note, permission_date, contact_publish_consent, verified_fields, fee_terms_text, fee_terms_agreed_on, private_contact_name, private_phone, created_at, updated_at) VALUES ('alfaiataria-sentru', 'Alfaiataria Sentru', 'Quick alterations (hems, zips, resizing) and ready-to-order shirts and trousers. Most alterations are ready in two to three days.', 'Colmera, Nain Feto, Dili', 'no', 'Tetum, Portuguese, Indonesian', NULL, date('now','-10 days'), NULL, '+67070000031', 'approved', 1, strftime('%Y-%m-%dT%H:%M:%fZ','now','-26 days','-0 hours'), 1, 'Agreed by phone with the owner', date('now','-28 days'), 1, '["description"]', '10% of the order value', date('now','-26 days'), 'Sr. Alberto', '+67070000032', strftime('%Y-%m-%dT%H:%M:%fZ','now','-45 days','-0 hours'), strftime('%Y-%m-%dT%H:%M:%fZ','now','-44 days','-0 hours'));
